mapper.select:
SELECT fd.folder_id
FROM doc_folder fd
WHERE fd.deleted_at IS NULL
  AND (
    fd.owner_id = #{userId}
    OR EXISTS (
        SELECT 1 FROM doc_folder_permission p
        WHERE p.folder_id = fd.folder_id
          AND 
    )
    OR EXISTS (
        SELECT 1 FROM doc_folder_permission p
        WHERE p.folder_id = ANY (
                  string_to_array(
                      trim(both '/' from COALESCE(fd.folder_path, '/')), '/'
                  )::bigint[]
              )
          AND 
    )
  )

mapper.sql:
(
    f.folder_id IN
        #{fid}
    OR EXISTS (
        SELECT 1 FROM doc_file_permission fp
        WHERE fp.file_id = f.file_id
          AND 
    )
)
